import{_ as s,o as a,c as t,a6 as i}from"./chunks/framework.ZMCvXf1_.js";const g=JSON.parse('{"title":"MCP (AI Agent Integration)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/automation/mcp.md","filePath":"guide/automation/mcp.md"}'),n={name:"guide/automation/mcp.md"};function o(r,e,h,d,l,c){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="mcp-ai-agent-integration" tabindex="-1">MCP (AI Agent Integration) <a class="header-anchor" href="#mcp-ai-agent-integration" aria-label="Permalink to “MCP (AI Agent Integration)”">​</a></h1><p>noorm runs an <a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">MCP</a> server over stdio. AI coding agents connect to it and get access to schema inspection, queries, changes, and config management.</p><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to “Quick Start”">​</a></h2><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Generate config for your agent (default: Claude Code)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or for Cursor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cursor</span></span></code></pre></div><p>This writes (or extends) the agent&#39;s MCP configuration file. The agent picks up the noorm server on next launch.</p><p>Pair it with the skill, which teaches the agent noorm&#39;s conventions rather than its tools:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> noormdev/noorm/skills</span></span></code></pre></div><p>MCP and the skill solve different halves of the same problem — MCP is what the agent can <em>do</em>, the skill is what it <em>knows</em>. An agent with MCP but no skill can query your schema and still write SDK code that wraps everything in <code>try</code>/<code>catch</code> this codebase never uses. See <a href="/getting-started/installation.html#install-the-agent-skill-optional">Installation</a>.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to “How It Works”">​</a></h2><p>The MCP server wraps noorm&#39;s internal RPC registry (the same command set behind the TUI) over stdio transport. Your agent connects, calls <code>noorm_help</code> to list available commands, then executes them through <code>run_noorm_cmd</code>.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>┌─────────────┐     stdio     ┌─────────────────┐     RPC      ┌──────────┐</span></span>
<span class="line"><span>│  AI Agent   │ ◄──────────► │  noorm mcp serve │ ◄──────────► │ Database │</span></span>
<span class="line"><span>└─────────────┘               └─────────────────┘              └──────────┘</span></span></code></pre></div><p>The server stays alive as long as the agent&#39;s process keeps stdin open.</p><h2 id="available-tools" tabindex="-1">Available Tools <a class="header-anchor" href="#available-tools" aria-label="Permalink to “Available Tools”">​</a></h2><p>The server exposes two MCP tools:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>run_noorm_cmd</code></td><td>Execute a noorm command (connect, sql, overview, list_configs, etc.)</td></tr><tr><td><code>noorm_help</code></td><td>List available commands and their parameter schemas</td></tr></tbody></table><p>Commands load from the RPC registry at runtime, so the tool list matches whatever noorm version you have installed.</p><h2 id="setup-by-agent" tabindex="-1">Setup by Agent <a class="header-anchor" href="#setup-by-agent" aria-label="Permalink to “Setup by Agent”">​</a></h2><h3 id="claude-code" tabindex="-1">Claude Code <a class="header-anchor" href="#claude-code" aria-label="Permalink to “Claude Code”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><p>Writes to <code>.mcp.json</code> in the project root. Claude Code reads this on startup.</p><h3 id="cursor" tabindex="-1">Cursor <a class="header-anchor" href="#cursor" aria-label="Permalink to “Cursor”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">noorm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cursor</span></span></code></pre></div><p>Writes to <code>.cursor/mcp.json</code>.</p><h2 id="manual-configuration" tabindex="-1">Manual Configuration <a class="header-anchor" href="#manual-configuration" aria-label="Permalink to “Manual Configuration”">​</a></h2><p>If you need to configure the server manually (e.g., for a custom agent), add this to your MCP config:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;noorm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">            &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;noorm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">            &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mcp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;serve&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>This is the exact entry <code>noorm mcp init</code> writes, so the two routes produce the same server.</p><p>The server uses stdio transport — no ports, no HTTP.</p><h2 id="what-the-agent-can-do" tabindex="-1">What the Agent Can Do <a class="header-anchor" href="#what-the-agent-can-do" aria-label="Permalink to “What the Agent Can Do”">​</a></h2><p>Once connected, your agent can:</p><ul><li><strong>Explore schemas</strong> — <code>overview</code>, <code>list</code>, <code>detail</code> for tables, columns, foreign keys, indexes</li><li><strong>Run SQL</strong> — <code>sql</code> executes a query and returns structured results</li><li><strong>Manage connections</strong> — <code>list_configs</code>, <code>connect</code>, <code>disconnect</code>, <code>status</code></li><li><strong>Apply changes</strong> — <code>change_run</code>, <code>change_ff</code>, <code>change_revert</code>, <code>change_history</code></li><li><strong>Build schemas</strong> — <code>run_build</code>, <code>run_file</code></li></ul><p>Config resolution and identity attribution work the same as the CLI. Access control does not: every config-scoped command is gated by the config&#39;s <strong><code>agent</code> role</strong> before its handler ever runs, and there is no confirmation flow — the agent gets an answer, not a prompt.</p><h2 id="access-roles" tabindex="-1">Access Roles <a class="header-anchor" href="#access-roles" aria-label="Permalink to “Access Roles”">​</a></h2><p>Every config declares a role per channel: <code>access: { user, agent }</code>. The <code>agent</code> role decides what an AI agent can do to that config — independently of what a human gets in the CLI/TUI.</p><p>The channel names <em>who is driving</em>, not which binary was invoked. An agent that gets refused here and shells out to <code>noorm</code> on the command line is still an agent, and gets the same <code>agent</code> role: the CLI detects the harness it was spawned from. Raising or lowering <code>agent</code> therefore governs both routes at once. See <a href="/guide/environments/configs.html#access-roles">Access Roles</a> for the detection rules and the <code>NOORM_CHANNEL</code> override.</p><p>A config that never declared <code>access</code> gets <code>{ user: &#39;admin&#39;, agent: &#39;viewer&#39; }</code>. Agents can explore and read on a fresh project without any setup; anything that writes needs you to raise the <code>agent</code> role on purpose.</p><table tabindex="0"><thead><tr><th>Role</th><th>What the agent can do</th></tr></thead><tbody><tr><td><code>viewer</code></td><td>Explore schema, run read-only SQL (<code>SELECT</code>, <code>SHOW</code>, <code>DESCRIBE</code>)</td></tr><tr><td><code>operator</code></td><td>Everything <code>viewer</code> can, plus SQL writes (<code>INSERT</code>/<code>UPDATE</code>/<code>DELETE</code>) — DDL and destructive commands (<code>change_run</code>, <code>run_build</code>, etc.) are still out of reach</td></tr><tr><td><code>admin</code></td><td>Writes, DDL, changes, builds, all frictionless. Permissions the matrix marks <code>confirm</code> even for <code>admin</code> (<code>db:teardown</code>, <code>db:destroy</code>, <code>config:write</code>) still deny on this channel</td></tr><tr><td><code>false</code></td><td>Invisible — the config does not exist on this channel</td></tr></tbody></table><p>Raw SQL is classified by what the statement actually does (<code>sql:read</code> / <code>sql:write</code> / <code>sql:ddl</code>), not by which command the agent called — an agent with <code>agent: viewer</code> gets a <code>SELECT</code> through but a same-shaped <code>INSERT</code> denied. <code>EXPLAIN</code> takes the class of the statement it wraps, because <code>EXPLAIN ANALYZE</code> runs that statement: <code>EXPLAIN SELECT</code> is a read, <code>EXPLAIN DELETE</code> is a write.</p><p>The matrix&#39;s <code>confirm</code> cells never prompt on this channel — they resolve straight to <strong>deny</strong>. An agent typing its own confirmation phrase would be theater, not a safeguard, and on the CLI it would need only <code>--yes</code>. If an agent legitimately needs to run changes on a database, give that config <code>agent: &#39;admin&#39;</code> — reserve it for configs where that&#39;s an acceptable risk (a disposable dev database, say), not production.</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Shape of the config&#39;s \`access\` field — set via \`noorm ui\` → Config → Edit,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or by editing the JSON before \`config import\` (see Config Sharing)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">access</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">admin</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # what you get in the CLI/TUI</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    agent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">viewer</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # what any connected agent gets</span></span></code></pre></div><h2 id="invisible-configs" tabindex="-1">Invisible Configs <a class="header-anchor" href="#invisible-configs" aria-label="Permalink to “Invisible Configs”">​</a></h2><p>Set <code>access.agent: false</code> to hide a config from agents entirely — over MCP it never appears in <code>list_configs</code> or <code>status</code>, and <code>connect</code> fails with the same error an unknown config name would produce. <code>noorm config list</code> filters it the same way when an agent runs it. An agent enumerating configs cannot tell the difference between &quot;doesn&#39;t exist&quot; and &quot;exists but is off-limits.&quot;</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h2><p>The MCP server uses the identity and config of the shell session that spawned it. It has no way to escalate privileges beyond what <code>noorm</code> itself can do, and it cannot escalate past the <code>agent</code> role a config was given — there is no <code>--force</code> override on this channel, and shelling out to the CLI reaches the same role rather than the human&#39;s.</p>`,44)])])}const k=s(n,[["render",o]]);export{g as __pageData,k as default};
